(()=>{
'use strict';
if(window.__atriaNeverRejectStudy485)return;
window.__atriaNeverRejectStudy485=true;
const KEY='atria.studyFallback.v483';
const norm=s=>(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim().replace(/\s+/g,' ');
let latestStudy=null,latestTs=0;
function capture(raw){raw=(raw||'').trim();let m=raw.match(/^\/estudio\s+(.+)$/i);if(!m)m=raw.match(/^\/orden\s+(.+)$/i);if(!m)return;latestStudy=m[1].trim();latestTs=Date.now()}
document.addEventListener('input',e=>{if(e.target?.matches?.('input,textarea'))capture(e.target.value)},true);
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target?.matches?.('input,textarea'))capture(e.target.value)},true);
document.addEventListener('submit',e=>{const el=e.target?.querySelector?.('input,textarea');if(el)capture(el.value)},true);
function inferStudyFromPage(){if(latestStudy&&Date.now()-latestTs<45000)return latestStudy;const text=document.body?.innerText||'';const re=/(?:Tú|Tu)\s*:\s*\/(?:estudio|orden)\s+([^\n\r]+)/gi;let m,last=null;while((m=re.exec(text)))last=(m[1]||'').trim();if(last){latestStudy=last;latestTs=Date.now();return last}return null}
function rejection(s){const n=norm(s);return n.includes('no reconozco ese estudio en este caso')||n.includes('no reconozco ese estudio')||n.includes('no pude traducir esa orden')||n.includes('estudio no disponible')||n.includes('no se puede solicitar ese estudio')}
function load(){try{return JSON.parse(localStorage.getItem(KEY)||'[]')}catch{return[]}}
function save(a){try{localStorage.setItem(KEY,JSON.stringify(a.slice(-100)))}catch{}}
function eta(study){const n=norm(study),urgent=/\burgente\b|\bstat\b/.test(n);if(/glucemia capilar|saturacion|oximetr|test rapido/.test(n))return urgent?8000:15000;if(/hemograma|lactato|gasometr|ionograma|electrol|glucemia|urea|creatin|hepatograma|amilasa|lipasa|tropon|coagul|pcr\b|vsg/.test(n))return urgent?20000:40000;if(/orina|sedimento|embarazo|beta hcg|dimero/.test(n))return urgent?25000:50000;if(/radiograf|\brx\b|electrocard|ecg/.test(n))return urgent?30000:60000;if(/ecograf|doppler/.test(n))return urgent?45000:90000;if(/tomograf|tac|\btc\b|angio/.test(n))return urgent?60000:105000;if(/resonan|rmn|\brm\b/.test(n))return urgent?120000:240000;if(/endosc|colonosc|broncosc|cistosc/.test(n))return urgent?120000:210000;if(/biops|anatomia patolog|citolog/.test(n))return urgent?180000:360000;if(/cultivo/.test(n))return urgent?180000:300000;if(/serolog|anticuerpo|antigen|hiv|hbsag|hcv|vdrl|tsh|t4|ferrit|b12|vitamina|folato/.test(n))return urgent?90000:180000;return urgent?30000:60000}
function result(study){const n=norm(study),fixed={lipasa:'Lipasa 34 U/L, dentro de rango.',amilasa:'Amilasa 62 U/L, dentro de rango.',tsh:'TSH 2,1 mUI/L.',troponina:'Troponina ultrasensible <6 ng/L, negativa.','vitamina b12':'Vitamina B12 420 pg/mL.',b12:'Vitamina B12 420 pg/mL.',ferritina:'Ferritina 118 ng/mL.'};if(fixed[n])return fixed[n];if(/cultivo/.test(n))return 'Sin desarrollo microbiológico significativo.';if(/serolog|anticuerpo|antigen|hiv|hbsag|hcv|vdrl/.test(n))return 'Resultado negativo / no reactivo.';if(/tomograf|tac|\btc\b|resonan|rmn|\brm\b|ecograf|eco|radiograf|\brx\b|pet|gammagraf/.test(n))return 'Sin hallazgos patológicos agudos relacionados con el cuadro actual.';if(/endosc|colonosc|broncosc|cistosc/.test(n))return 'Sin lesiones macroscópicas significativas relacionadas con el cuadro actual.';if(/biops|anatomia patolog|citolog/.test(n))return 'Sin alteraciones histopatológicas específicas relacionadas con el cuadro actual.';return 'Resultado dentro de parámetros de referencia, sin alteraciones clínicamente significativas.'}
function enqueue(study){const rows=load(),sig=norm(study),now=Date.now();const existing=rows.find(x=>norm(x.study)===sig&&now-(x.requestedAt||0)<5000);if(existing)return existing;const rec={id:'s'+now+Math.random().toString(36).slice(2,6),study,status:'pending',requestedAt:now,result:null,etaMs:eta(study)};rows.push(rec);save(rows);window.dispatchEvent(new CustomEvent('atria:study-result',{detail:rec}));setTimeout(()=>{const all=load(),x=all.find(v=>v.id===rec.id);if(!x)return;x.status='ready';x.result=result(study);x.readyAt=Date.now();save(all);window.dispatchEvent(new CustomEvent('atria:study-result',{detail:x}))},rec.etaMs);return rec}
function replaceTextNode(node,study){const s=node.nodeValue||'';if(!rejection(s))return false;let next=s;next=next.replace(/No reconozco ese estudio en este caso\.?/ig,study+' solicitado. Resultado pendiente.');next=next.replace(/No reconozco ese estudio\.?/ig,study+' solicitado. Resultado pendiente.');next=next.replace(/No pude traducir esa orden\.[^.\n]*/ig,study+' solicitado. Resultado pendiente.');next=next.replace(/Estudio no disponible(?: en este caso)?\.?/ig,study+' solicitado. Resultado pendiente.');next=next.replace(/No se puede solicitar ese estudio\.?/ig,study+' solicitado. Resultado pendiente.');if(next!==s){node.nodeValue=next;return true}return false}
function scrub(root){const study=inferStudyFromPage()||'Estudio';let changed=false;if(root?.nodeType===3)changed=replaceTextNode(root,study)||changed;const base=root?.nodeType===1?root:document.body;if(base){const w=document.createTreeWalker(base,NodeFilter.SHOW_TEXT);let n;while((n=w.nextNode()))changed=replaceTextNode(n,study)||changed}if(changed&&study!=='Estudio')enqueue(study)}
const mo=new MutationObserver(ms=>{for(const m of ms){if(m.type==='characterData')scrub(m.target);for(const n of m.addedNodes)scrub(n)}});if(document.body)mo.observe(document.body,{childList:true,subtree:true,characterData:true});
setInterval(()=>scrub(document.body),700);scrub(document.body);
})();